/**
 * 배열을 keyFn(item) 반환값 기준으로 묶어 객체로 반환합니다.
 *
 * @param {Array} arr - 그룹화할 배열
 * @param {Function} keyFn - 각 아이템에서 그룹 키를 추출하는 함수
 * @returns {Object} { key: [items...] } 형태의 객체
 */
function groupBy(arr, keyFn) {
  if (!Array.isArray(arr)) {
    throw new TypeError('arr must be an array');
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError('keyFn must be a function');
  }

  const result = Object.create(null);

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i, arr);

    if (!Object.prototype.hasOwnProperty.call(result, key)) {
      result[key] = [];
    }
    result[key].push(item);
  }

  return result;
}

module.exports = { groupBy };
```

## 사용 예시

```js
const { groupBy } = require('./groupBy');

// 1) 숫자를 짝수/홀수로 그룹화
const nums = [1, 2, 3, 4, 5, 6];
console.log(groupBy(nums, (n) => (n % 2 === 0 ? 'even' : 'odd')));
// { odd: [1, 3, 5], even: [2, 4, 6] }

// 2) 객체 배열을 특정 속성 기준으로 그룹화
const users = [
  { name: 'Kim', team: 'A' },
  { name: 'Lee', team: 'B' },
  { name: 'Park', team: 'A' },
];
console.log(groupBy(users, (u) => u.team));
// {
//   A: [{ name: 'Kim', team: 'A' }, { name: 'Park', team: 'A' }],
//   B: [{ name: 'Lee', team: 'B' }]
// }

// 3) 문자열 길이로 그룹화
const words = ['a', 'bb', 'cc', 'ddd'];
console.log(groupBy(words, (w) => w.length));
// { '1': ['a'], '2': ['bb', 'cc'], '3': ['ddd'] }
```

### 구현 포인트

- **`Object.create(null)`**: 프로토타입이 없는 순수 객체를 사용해 `__proto__` 같은 키가 들어와도 안전하게 동작합니다.
- **`hasOwnProperty.call(...)`**: 상속된 속성과의 충돌 없이 키 존재 여부를 정확히 검사합니다.
- **`keyFn(item, i, arr)`**: `Array.map` 등과 유사하게 인덱스와 원본 배열도 콜백에 전달합니다.
- 반환되는 키는 객체 키 규칙에 따라 **문자열로 변환**됩니다 (숫자 키도 `'1'`처럼 처리됨).

