    const list = this._events.get(event);
    if (!list || list.length === 0) return 0;

    // 스냅샷 순회: emit 도중 off/on이 원본 배열을 바꿔도 안전
    const snapshot = list.slice();
    let called = 0;

    for (const listener of snapshot) {
      // once는 실행 "전"에 제거 → 재진입 emit에서 두 번 실행 방지
      if (listener.once) {
        this._removeListenerRef(event, listener);
      }
      listener.fn.apply(this, args);
      called++;
    }

    return called;
  }

