let count = 0;
e2.once('tick', () => {
  count++;
  e2.emit('tick'); // 이미 제거됨 → 재실행 안 됨
});
e2.emit('tick');
console.log(count); // 1

// emit 중 off 안전성
const e3 = new Emitter();
const h1 = () => { e3.off('y', h2); logs.push('h1'); };
const h2 = () => logs.push('h2'); // h1이 제거했지만 이번 emit엔 이미 스냅샷에 있음
e3.on('y', h1).on('y', h2);
e3.emit('y'); // 안전하게 실행됨
