'use strict';

/**
 * 가벼운 EventEmitter 구현 (CommonJS)
 *
 * 설계 포인트
 *  - emit()은 리스너 배열의 "스냅샷(복사본)"을 순회하므로,
 *    핸들러 안에서 on/off/once를 호출해도 순회가 깨지지 않는다.
 *  - 스냅샷 순회 중에도 "이미 off된 리스너"는 실제 목록을 다시 확인해서 건너뛴다.
 *  - once 래퍼는 "실행 전"에 목록에서 제거하므로,
 *    핸들러 안에서 같은 이벤트를 다시 emit해도(재진입) 두 번 실행되지 않는다.
 */
class Emitter {
  constructor() {
    // event(string|symbol) -> listener[]  (Map이라 심볼/'__proto__' 키도 안전)
    this._events = new Map();
  }

  /** 구독. this 반환(체이닝) */
  on(event, fn) {
    if (typeof fn !== 'function') {
      throw new TypeError('listener must be a function');
    }
    const list = this._events.get(event);
    if (list) list.push(fn);
    else this._events.set(event, [fn]);
    return this;
  }

  /** 1회만 실행. this 반환(체이닝) */
  once(event, fn) {
    if (typeof fn !== 'function') {
      throw new TypeError('listener must be a function');
    }
    // 화살표 함수가 아니어야 emit이 넘겨주는 this가 그대로 전달된다.
    function wrapper(...args) {
      return fn.apply(this, args);
    }
    wrapper.listener = fn; // off(event, 원본fn)으로도 제거 가능하게
    wrapper.once = true;
    return this.on(event, wrapper);
  }

  /**
   * 구독 해제. this 반환(체이닝)
   *  - off(event, fn) : 해당 핸들러 1개 제거(once 원본 함수로도 제거 가능)
   *  - off(event)     : 해당 이벤트의 모든 핸들러 제거
   *  - off()          : 전체 제거
   */
  off(event, fn) {
    if (arguments.length === 0) {
      this._events.clear();
      return this;
    }
    if (fn === undefined) {
      this._events.delete(event);
      return this;
    }
    const list = this._events.get(event);
    if (!list) return this;

    const i = list.findIndex((l) => l === fn || l.listener === fn);
    if (i !== -1) {
      list.splice(i, 1); // 배열을 새로 만들지 않고 제자리 수정(스냅샷과 분리됨)
      if (list.length === 0) this._events.delete(event);
    }
    return this;
  }

  /**
   * 등록 순서대로 호출. 실제로 호출한 리스너 수 반환.
   * (emit 도중 off된 리스너는 호출하지 않으므로 카운트에도 포함되지 않는다)
   */
  emit(event, ...args) {
    const list = this._events.get(event);
    if (!list || list.length === 0) return 0;

    const snapshot = list.slice(); // 순회 중 목록이 바뀌어도 안전
    let called = 0;

    for (const listener of snapshot) {
      const current = this._events.get(event);
      // emit 도중 제거된 리스너는 스킵
      if (!current || current.indexOf(listener) === -1) continue;

      // once는 "실행 전에" 제거 → 재진입 emit에서 중복 실행 방지
      if (listener.once) this.off(event, listener);

      called++;
      listener.call(this, ...args);
    }
    return called;
  }

  // ---- 부가 유틸 (선택) ----

  /** 현재 등록된 리스너 목록(복사본). once는 원본 함수로 노출 */
  listeners(event) {
    const list = this._events.get(event);
    return list ? list.map((l) => l.listener || l) : [];
  }

  listenerCount(event) {
    const list = this._events.get(event);
    return list ? list.length : 0;
  }

  eventNames() {
    return [...this._events.keys()];
  }
}

