from collections import defaultdict
from decimal import Decimal, InvalidOperation
import re


_RESPONSE_TIME_RE = re.compile(r"^(?:\d+(?:\.\d*)?|\.\d+)ms$")


def summarize(lines: list[str]) -> dict:
    total = 0
    error_count = 0
    by_status: dict[int, int] = defaultdict(int)
    path_times: dict[str, list[Decimal | int]] = {}

    for line in lines:
        fields = line.split()
        if len(fields) < 5:
            continue

        _, _, path, status_text, time_text = fields[:5]

        try:
            status = int(status_text)
            if not _RESPONSE_TIME_RE.fullmatch(time_text):
                continue
            response_time = Decimal(time_text[:-2])
        except (ValueError, InvalidOperation):
            continue

        total += 1
        by_status[status] += 1

        if 500 <= status <= 599:
            error_count += 1

        if path not in path_times:
            path_times[path] = [Decimal(0), 0]
        path_times[path][0] += response_time
        path_times[path][1] += 1

    slowest_path = None
    if path_times:
        slowest_path = min(
            path_times,
            key=lambda path: (
                -(path_times[path][0] / path_times[path][1]),
                path,
            ),
        )

    return {
        "total": total,
        "by_status": dict(by_status),
        "slowest_path": slowest_path,
        "error_rate": round(error_count / total, 4) if total else 0.0,
    }
