package main

import (
	"fmt"
	"sync"
	"sync/atomic"
	"time"
)

// MapConcurrent 은 in 의 각 원소에 f 를 적용한 결과를 돌려준다.
// 동시에 실행되는 f 의 개수는 최대 limit 개이며(limit <= 0 이면 1),
// 반환 슬라이스는 입력 순서를 그대로 유지한다.
func MapConcurrent(in []int, limit int, f func(int) int) []int {
	if in == nil {
		return nil
	}
	out := make([]int, len(in))
	if len(in) == 0 {
		return out
	}
	if limit <= 0 {
		limit = 1
	}
	if limit > len(in) {
		limit = len(in) // 필요 이상으로 워커를 만들지 않는다
	}

	// 워커 풀: 인덱스를 나눠 받아 out[i] 에 직접 쓴다.
	// 각 워커가 서로 다른 인덱스에만 쓰므로 데이터 레이스가 없고,
	// 인덱스로 저장하기 때문에 완료 순서와 무관하게 입력 순서가 보존된다.
	idxCh := make(chan int)

	var wg sync.WaitGroup
	wg.Add(limit)
	for w := 0; w < limit; w++ {
		go func() {
			defer wg.Done()
			for i := range idxCh {
				out[i] = f(in[i])
			}
		}()
	}

	for i := range in {
		idxCh <- i
	}
	close(idxCh)
	wg.Wait()

	return out
}

func main() {
	in := make([]int, 20)
	for i := range in {
		in[i] = i + 1
	}

	// 동시 실행 개수가 limit 을 넘지 않는지 확인용 카운터
	var cur, max int64

	f := func(x int) int {
		n := atomic.AddInt64(&cur, 1)
		for {
			m := atomic.LoadInt64(&max)
			if n <= m || atomic.CompareAndSwapInt64(&max, m, n) {
				break
			}
		}
		time.Sleep(20 * time.Millisecond) // 일부러 느린 작업
		atomic.AddInt64(&cur, -1)
		return x * x
	}

	start := time.Now()
	out := MapConcurrent(in, 4, f)
	elapsed := time.Since(start)

	fmt.Println("in :", in)
	fmt.Println("out:", out)
	fmt.Printf("elapsed: %v, max concurrency: %d\n", elapsed.Round(time.Millisecond), max)

	// 엣지 케이스
	fmt.Println(MapConcurrent(nil, 4, f))                 // []
	fmt.Println(MapConcurrent([]int{}, 4, f))             // []
	fmt.Println(MapConcurrent([]int{1, 2, 3}, 0, f))      // limit<=0 → 1 (순차)
	fmt.Println(MapConcurrent([]int{1, 2, 3}, -5, f))     // 마찬가지
	fmt.Println(MapConcurrent([]int{1, 2, 3}, 100, f))    // limit > len(in)
}
```

포인트 세 가지:

- **순서 보존**: 결과를 채널로 모으지 않고 `out[i] = f(in[i])` 처럼 인덱스에 직접 쓴다. 워커마다 쓰는 인덱스가 겹치지 않으므로 뮤텍스 없이도 안전하고(`go test -race` 통과), 완료 순서와 무관하게 입력 순서가 유지된다.
- **동시성 제한**: 고루틴을 `len(in)` 개 띄우고 세마포어로 막는 대신, 워커를 `limit` 개만 띄우고 인덱스를 채널로 분배한다. 입력이 아주 커도 고루틴 수가 `limit` 으로 고정된다.
- **정리**: 인덱스 채널을 `close` 하면 워커 루프가 끝나고 `wg.Wait()` 로 전부 회수하므로 고루틴 누수가 없다.

