function page(rows, cursor, size) {
  if (size < 1) {
    throw new RangeError('size must be at least 1');
  }

  let startIndex = 0;

  if (cursor !== null) {
    const cursorIndex = rows.findIndex((row) => row.id === cursor);

    if (cursorIndex === -1) {
      return { items: [], nextCursor: null };
    }

    startIndex = cursorIndex + 1;
  }

  const items = rows.slice(startIndex, startIndex + size);
  const hasMore = startIndex + items.length < rows.length;
  const nextCursor = hasMore && items.length > 0
    ? items[items.length - 1].id
    : null;

  return { items, nextCursor };
}

module.exports = { page };
