 * (rows가 id 기준 오름차순으로 정렬돼 있다는 전제를 이용)
 */
function indexOfId(rows, id) {
  let lo = 0;
  let hi = rows.length - 1;

  while (lo <= hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    const midId = rows[mid].id;

    if (midId === id) return mid;
    if (midId < id) lo = mid + 1;
    else hi = mid - 1;
  }
  return -1;
