 *
 * @param {Array<{id: *}>} rows  id 오름차순으로 정렬된 배열
 * @param {*} cursor             null/undefined면 처음부터, 아니면 그 id "다음"부터
 * @param {number} size          한 페이지 크기 (1 이상의 정수)
 * @returns {{items: Array<{id: *}>, nextCursor: *|null}}
 */
function page(rows, cursor, size) {
  if (!Array.isArray(rows)) {
    throw new TypeError('rows must be an array');
  }
  if (typeof size !== 'number') {
    throw new TypeError('size must be a number');
  }
  // NaN, 소수, 0 이하, -Infinity 등은 모두 유효하지 않은 페이지 크기
  if (!Number.isInteger(size) || size < 1) {
    throw new RangeError('size must be an integer >= 1');
  }

