    const mid = lo + Math.floor((hi - lo) / 2);
    const midId = rows[mid].id;

    if (midId === id) return mid;
    if (midId < id) lo = mid + 1;
    else hi = mid - 1;
  }
  return -1;
}

/**
 * 커서 기반 페이지네이션.
 *
 * @param {Array<{id: *}>} rows  id 오름차순으로 정렬된 배열
 * @param {*} cursor             null/undefined면 처음부터, 아니면 그 id "다음"부터
 * @param {number} size          한 페이지 크기 (1 이상의 정수)
 * @returns {{items: Array<{id: *}>, nextCursor: *|null}}
 */
function page(rows, cursor, size) {
  if (!Array.isArray(rows)) {
    throw new TypeError('rows must be an array');
  }
  if (typeof size !== 'number') {
    throw new TypeError('size must be a number');
  }
  // NaN, 소수, 0 이하, -Infinity 등은 모두 유효하지 않은 페이지 크기
  if (!Number.isInteger(size) || size < 1) {
    throw new RangeError('size must be an integer >= 1');
  }

  let start;
  if (cursor === null || cursor === undefined) {
    start = 0;
  } else {
    const idx = indexOfId(rows, cursor);
    if (idx === -1) {
      // 커서가 목록에 없는 id
      return { items: [], nextCursor: null };
    }
    start = idx + 1; // 커서 id "다음"부터
  }

  const end = Math.min(start + size, rows.length);
  const items = rows.slice(start, end);

  // 뒤에 남은 행이 있을 때만 nextCursor를 준다.
  const nextCursor = end < rows.length ? items[items.length - 1].id : null;

  return { items, nextCursor };
}

module.exports = { page };
```

동작 요약:

- `cursor === null` → 처음부터 `size`개.
- `cursor`가 존재하는 id → 그 id **다음**부터 `size`개.
- 마지막 페이지(뒤에 남은 행이 없음)면 `nextCursor: null`.
- `start`가 배열 끝을 넘으면 `items: []`, `nextCursor: null` (`end === rows.length`이므로 자동 처리).
- 커서가 목록에 없으면 `{ items: [], nextCursor: null }`.
- `size < 1`(또는 정수가 아님/NaN)이면 `RangeError`.

