    email_index: dict[str, int] = {}
    phone_index: dict[str, int] = {}

    for row in rows:
        name = (row.get("name") or "").strip()
        email = norm_email(row.get("email") or "")
        phone = norm_phone(row.get("phone") or "")
        orders = row.get("orders") or 0

        # 매칭 대상 찾기 (이메일 우선, 그다음 휴대폰)
        idx = None
        if email and email in email_index:
            idx = email_index[email]
        elif phone and phone in phone_index:
            idx = phone_index[phone]

        if idx is None:
            # 새 고객 추가
            new_rec = {
                "name": name,
                "email": email,
                "phone": phone,
                "orders": orders,
            }
            merged.append(new_rec)
            new_idx = len(merged) - 1
            if email:
                email_index[email] = new_idx
            if phone:
                phone_index[phone] = new_idx
        else:
            # 기존 고객에 병합
            rec = merged[idx]

            # name: 더 긴 쪽, 같으면 먼저 나온 쪽(기존 유지)
            if len(name) > len(rec["name"]):
                rec["name"] = name

            # email: 값이 있는 것 중 먼저 나온 것
            if not rec["email"] and email:
                rec["email"] = email

            # phone: 값이 있는 것 중 먼저 나온 것
            if not rec["phone"] and phone:
                rec["phone"] = phone

            # orders: 합산
            rec["orders"] += orders

            # 새로 채워진 email/phone 으로 인덱스 갱신
            if rec["email"] and rec["email"] not in email_index:
                email_index[rec["email"]] = idx
            if rec["phone"] and rec["phone"] not in phone_index:
                phone_index[rec["phone"]] = idx

    return merged
