"""
고객 레코드 중복 병합 유틸리티.

판정 규칙 (우선순위 순)
  1) email : 앞뒤 공백 무시 + 대소문자 무시하여 같으면 동일 고객
  2) phone : 숫자만 남긴 정규형이 같으면 동일 고객
             (국가번호 82 는 떼고 앞에 0 을 붙여 비교)
  3) 그 외 : 이름이 같아도 다른 고객으로 본다

이메일/휴대폰 연결은 전이적으로 적용된다.
  A-B 는 이메일이 같고, B-C 는 휴대폰이 같으면 A, B, C 는 모두 같은 고객이다.
"""

from __future__ import annotations

import re
from typing import Any

_NON_DIGIT = re.compile(r"\D")


# ---------------------------------------------------------------- 정규화 ----
def normalize_email(value: Any) -> str:
    """이메일 정규형: 앞뒤 공백 제거 + 소문자."""
    if not isinstance(value, str):
        return ""
    return value.strip().lower()


def normalize_phone(value: Any) -> str:
    """
    휴대폰 정규형: 숫자만 남긴 문자열.

        '010-1234-5678'      -> '01012345678'
        '01012345678'        -> '01012345678'
        '+82 10 1234 5678'   -> '01012345678'
        '+82 (0)10-1234-5678'-> '01012345678'
        '0082 10 1234 5678'  -> '01012345678'
    """
    if not isinstance(value, str):
        return ""

    digits = _NON_DIGIT.sub("", value)
    if not digits:
        return ""

    # 국제 표기 처리: 00 82 ... / 82 ...
    if digits.startswith("0082"):
        digits = digits[4:]
    elif digits.startswith("82"):
        digits = digits[2:]
    else:
        # 국내 표기는 그대로 사용 (한국 번호는 0 으로 시작하므로 82 로 시작할 일이 없다)
        return digits

    # 국가번호를 뗀 뒤에는 앞에 0 을 붙인다. ('+82 010 ...' 처럼 이미 0 이면 그대로)
    return digits if digits.startswith("0") else "0" + digits


def _clean_name(value: Any) -> str:
    """이름 정규형: 앞뒤 공백 제거."""
    if not isinstance(value, str):
        return ""
    return value.strip()


def _to_int(value: Any) -> int:
    """orders 값을 정수로. 변환 불가/None 은 0."""
    if isinstance(value, bool):
        return int(value)
    if isinstance(value, int):
        return value
    try:
        return int(float(value))
    except (TypeError, ValueError):
        return 0


