def first_free(busy, duration, day_start=9 * 60, day_end=18 * 60):
    if duration < 0:
        raise ValueError("duration은 0 이상이어야 합니다.")
    if day_start > day_end:
        raise ValueError("day_start는 day_end보다 작거나 같아야 합니다.")
    if duration == 0:
        return day_start

    intervals = sorted(
        (max(start, day_start), min(end, day_end))
        for start, end in busy
        if end > day_start and start < day_end and end > start
    )

    cursor = day_start

    for start, end in intervals:
        if start - cursor >= duration:
            return cursor
        cursor = max(cursor, end)

    if day_end - cursor >= duration:
        return cursor

    return None
